import sys
from collections import defaultdict

def countSubstring(S):
    n = len(S)
    prefix = 0
    balance_count = defaultdict(int)
    balance_count[0] = 1
    total = 0

    for char in S:
        if char == '1':
            prefix += 1
        else:
            prefix -= 1

        if prefix > 0:
            total += balance_count[0]

        if prefix > 1:
            for k in range(1, prefix):
                if k in balance_count:
                    total += balance_count[k]

        balance_count[prefix] += 1

    return total

def main():
    S = sys.stdin.read().strip()
    result = countSubstring(S)
    print(result)

if __name__ == "__main__":
    main()
